export function init(root) {
    if (!root || typeof root.appendChild !== "function")
        throw new TypeError("init(root): root must be an Element");
    if (root.querySelector('[data-state="skeleton"]')) return;   // idempotent
    const shell = document.createElement("div");
    shell.dataset.state = "skeleton";
    shell.setAttribute("aria-busy", "true");
    root.appendChild(shell);
}

// Browser only.  Keeps the module importable from node:test without side effects.
if (typeof document !== "undefined") {
    document.addEventListener("DOMContentLoaded", () => {
        const root = document.getElementById("app");
        if (root) init(root);
    });
}

// tests/js/main.test.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { init } from "../../game/static/game/js/main.js";

test("init is exported as a function", () => {
    assert.equal(typeof init, "function");
});

test("init rejects a non-element root", () => {
    assert.throws(() => init(null), TypeError);
    assert.throws(() => init({}), TypeError);
});

test("importing the entry module has no side effects in node", () => {
    assert.equal(typeof globalThis.document, "undefined");
});

// run:  node --test tests/js

_active = False
@contextmanager def instrument() -> Iterator[Accumulator]: global _active if _active: raise RuntimeError("instrument() is not re-entrant") acc = Accumulator() originals = { (DancingLinks, "_apply_row"): DancingLinks._apply_row, (DancingLinks, "givens"): DancingLinks.givens, (DancingLinks, "search"): DancingLinks.search, (solver, "alternative_exists"): solver.alternative_exists, (generator, "alternative_exists"): generator.alternative_exists, # EF1 } _active = True try: install counting wrappers that delegate to originals and bump acc yield acc finally: for (owner, name), fn in originals.items(): setattr(owner, name, fn) _active = False
# the alternative_exists wrapper also records the probe histogram: # n = count of values that pass peers_forbid and differ from `exclude` # acc.alternative_calls += 1 ; acc.probes += n ; acc.zero_probe_calls += (n == 0)

def workload(dim, trials, seed):
    if trials < 1: raise ValueError(f"trials must be >= 1, got {trials}")
    spec = spec_for(dim)                       # raises for unsupported dims
    rng = random.Random(seed)                  # local rng, never random.seed()
    return [generator.generate_puzzle(dim=spec, rng=rng) for _ in range(trials)]

def ab_timing(dims=(9, 12, 16), trials=10, seed=7):
    for dim in dims:
        rng_free_times = []
        for i in range(trials):
            t0 = perf_counter(); workload(dim, 1, seed + i); rng_free_times.append(perf_counter() - t0)
        print(dim, trials, seed, median(rng_free_times), max(rng_free_times))

def main():
    compare_uniqueness_checks(); iteration_distribution(); generation_cost()   # existing
    call_counts(); profile_section(); ab_timing()                              # new
